def _is_number(token):
    return token.lstrip('-').isdigit() and token.count('-') <= 1 and (
        not token.startswith('-') or len(token) > 1
    ) and '-' not in token[1:]


def _pop(stack, count):
    if len(stack) < count:
        raise StackUnderflowError('Insufficient number of items in stack')
    values = stack[-count:]
    del stack[-count:]
    return values


def _add(stack):
    a, b = _pop(stack, 2)
    stack.append(a + b)


def _sub(stack):
    a, b = _pop(stack, 2)
    stack.append(a - b)


def _mul(stack):
    a, b = _pop(stack, 2)
    stack.append(a * b)


def _div(stack):
    a, b = _pop(stack, 2)
    if b == 0:
        raise ZeroDivisionError('divide by zero')
    quotient = abs(a) // abs(b)
    stack.append(quotient if (a < 0) == (b < 0) else -quotient)


def _dup(stack):
    (a,) = _pop(stack, 1)
    stack.extend((a, a))


def _drop(stack):
    _pop(stack, 1)


def _swap(stack):
    a, b = _pop(stack, 2)
    stack.extend((b, a))


def _over(stack):
    a, b = _pop(stack, 2)
    stack.extend((a, b, a))


